begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not has_function_privilege('authenticated','private.post_money_movement(text,uuid,integer,jsonb)','EXECUTE') and not has_function_privilege('anon','private.post_money_movement(text,uuid,integer,jsonb)','EXECUTE'),'Semantic movement kernel is private');
select ok((select proowner='carrier_finance'::regrole and prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='private.post_money_movement(text,uuid,integer,jsonb)'::regprocedure),'Movement owner is restricted with a pinned search path');
select ok(not has_table_privilege('carrier_finance','private.trip_recognition','INSERT,UPDATE,DELETE'),'Payment kernel cannot create another earning recognition');
select ok(not pg_has_role('postgres','carrier_finance','SET') and not pg_has_role('postgres','carrier_security','SET'),'Temporary migration role access revoked');
select ok(not has_schema_privilege('carrier_finance','private','CREATE'),'No lingering finance schema mutation');
select ok((select bool_and(tgenabled='O') from pg_trigger where tgname in('funded_trip_identity','funded_consignment_identity')),'Funded draft identity guards enabled');
select set_config('request.jwt.claims','{}',true);
set local role authenticated;
select throws_ok($$select public.post_financial_event('ADVANCE',gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','Advance requires a live staff session');
select throws_ok($$select public.post_financial_event('REFUND',gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','Refund requires a live staff session');
select throws_ok($$select public.post_financial_event('CUSTODY_TRANSFER',gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','Custody transfer requires a live staff session');
select throws_ok($$select public.post_financial_event('PERSONAL_FUNDING',gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','Personal funding requires a live staff session');
select throws_ok($$select public.post_financial_event('REIMBURSEMENT',gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','Reimbursement requires live staff in T09');
reset role;
select * from finish();
rollback;
